package ems.controller;

import ems.dto.*; import ems.model.*; import ems.repository.*; import ems.service.*; import service.GroupChatService;
import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid;
import org.springframework.beans.factory.annotation.Value; import org.springframework.core.io.InputStreamResource; import org.springframework.http.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import org.springframework.web.server.ResponseStatusException;
import java.io.*; import java.nio.file.*; import java.util.*; import java.util.stream.Collectors;

@RestController @RequestMapping("/api/ems")
public class EmsController {
    private final EmsAccessService access; private final EmployeeRepository employees; private final DepartmentRepository departments; private final ProjectRepository projects; private final ProjectMemberRepository members; private final AttendanceRepository attendance; private final LeaveRequestRepository leaves; private final SalaryRecordRepository payroll; private final EmployeeDocumentRepository documents; private final PerformanceReviewRepository reviews; private final AnnouncementRepository announcements; private final EmsNotificationService notifications; private final GroupChatService chatGroups; private final SystemSettingRepository settings;
    @Value("${ems.files.directory:${java.io.tmpdir}/teamconnect-ems-files}") private String fileDirectory;
    public EmsController(EmsAccessService a,EmployeeRepository e,DepartmentRepository d,ProjectRepository p,ProjectMemberRepository m,AttendanceRepository at,LeaveRequestRepository l,SalaryRecordRepository s,EmployeeDocumentRepository doc,PerformanceReviewRepository r,AnnouncementRepository an,EmsNotificationService n,GroupChatService g,SystemSettingRepository ss){access=a;employees=e;departments=d;projects=p;members=m;attendance=at;leaves=l;payroll=s;documents=doc;reviews=r;announcements=an;notifications=n;chatGroups=g;settings=ss;}

    @GetMapping("/employees") public Object employeeList(HttpServletRequest r){access.requireHrOrAdmin(r);return employees.findAllByOrderByNameAsc();}
    @GetMapping("/employees/me") public Employee employeeMe(HttpServletRequest r){return access.currentEmployee(r);}
    @GetMapping("/employees/{id}") public Employee employee(@PathVariable Long id,HttpServletRequest r){return access.requireEmployee(r,id);}
    @PostMapping("/employees") public Employee createEmployee(@Valid @RequestBody EmployeeRequest x,HttpServletRequest r){access.requireHrOrAdmin(r);return employees.save(employeeFrom(x));}
    @PutMapping("/employees/{id}") public Employee updateEmployee(@PathVariable Long id,@Valid @RequestBody EmployeeRequest x,HttpServletRequest r){access.requireHrOrAdmin(r);Employee e=employees.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Employee not found"));copy(e,x);return employees.save(e);}
    @PatchMapping("/employees/{id}/status") public Employee employeeStatus(@PathVariable Long id,@RequestParam @jakarta.validation.constraints.NotBlank String status,HttpServletRequest r){access.requireHrOrAdmin(r);Employee e=employees.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Employee not found"));e.setStatus(status.toUpperCase(Locale.ROOT));return employees.save(e);}

    @GetMapping("/departments") public List<Department> departments(HttpServletRequest r){access.userId(r);return departments.findAll();}
    @PostMapping("/departments") public Department createDepartment(@Valid @RequestBody DepartmentRequest x,HttpServletRequest r){access.requireHrOrAdmin(r);Department d=new Department();d.setName(x.name());d.setDescription(x.description());Department saved=departments.save(d);try{d.setTeamConnectChannelId(chatGroups.create("Department · "+d.getName(),access.userId(r)).getId());saved=departments.save(d);}catch(RuntimeException ignored){}return saved;}
    @PutMapping("/departments/{id}") public Department updateDepartment(@PathVariable Long id,@Valid @RequestBody DepartmentRequest x,HttpServletRequest r){access.requireHrOrAdmin(r);Department d=departments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Department not found"));d.setName(x.name());d.setDescription(x.description());return departments.save(d);}
    @PostMapping("/departments/{id}/members/{employeeId}") public Object addDepartmentMember(@PathVariable Long id,@PathVariable Long employeeId,HttpServletRequest r){access.requireHrOrAdmin(r);Department d=departments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Department not found"));Employee e=employees.findById(employeeId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Employee not found"));if(d.getTeamConnectChannelId()==null||e.getTeamConnectUserId()==null)throw new ResponseStatusException(HttpStatus.CONFLICT,"Department channel or TeamConnect user mapping is missing");chatGroups.addMember(d.getTeamConnectChannelId(),e.getTeamConnectUserId());return Map.of("success",true,"channelId",d.getTeamConnectChannelId());}

    @GetMapping("/projects") public List<Project> projectList(HttpServletRequest r){access.userId(r);return projects.findAllByOrderByStartDateDesc();}
    @PostMapping("/projects") public Project createProject(@Valid @RequestBody ProjectRequest x,HttpServletRequest r){access.requireHrOrAdmin(r);Project p=projects.save(projectFrom(x));try{p.setTeamConnectChannelId(chatGroups.create("Project · "+p.getProjectName(),access.userId(r)).getId());return projects.save(p);}catch(RuntimeException ignored){return p;}}
    @PutMapping("/projects/{id}") public Project updateProject(@PathVariable Long id,@Valid @RequestBody ProjectRequest x,HttpServletRequest r){access.requireHrOrAdmin(r);Project p=projects.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Project not found"));p.setProjectName(x.projectName());p.setDescription(x.description());p.setStartDate(x.startDate());p.setEndDate(x.endDate());p.setStatus(x.status());return projects.save(p);}
    @PostMapping("/projects/{id}/members/{employeeId}") public Object addMember(@PathVariable Long id,@PathVariable Long employeeId,HttpServletRequest r){access.requireHrOrAdmin(r);if(!projects.existsById(id)||!employees.existsById(employeeId))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Project or employee not found");return members.save(new ProjectMember(id,employeeId));}
    @GetMapping("/projects/me") public List<Project> myProjects(HttpServletRequest r){Long id=access.currentEmployee(r).getId();return members.findByIdEmployeeId(id).stream().map(x->projects.findById(x.getId().getProjectId()).orElse(null)).filter(Objects::nonNull).toList();}

    @GetMapping("/attendance/me") public List<Attendance> myAttendance(HttpServletRequest r){return attendance.findByEmployeeIdOrderByDateDesc(access.currentEmployee(r).getId());}
    @GetMapping("/attendance") public List<Attendance> allAttendance(HttpServletRequest r){access.requireHrOrAdmin(r);return attendance.findAll();}
    @PostMapping("/attendance") public Attendance saveAttendance(@Valid @RequestBody AttendanceRequest x,HttpServletRequest r){access.requireHrOrAdmin(r);Attendance a=new Attendance();a.setEmployeeId(x.employeeId());a.setDate(x.date());a.setStatus(x.status().toUpperCase(Locale.ROOT));a.setCheckIn(x.checkIn());a.setCheckOut(x.checkOut());a.setNotes(x.notes());return attendance.save(a);}

    @GetMapping("/leave/me") public List<LeaveRequest> myLeave(HttpServletRequest r){return leaves.findByEmployeeIdOrderByAppliedOnDesc(access.currentEmployee(r).getId());}
    @GetMapping("/leave") public List<LeaveRequest> allLeave(HttpServletRequest r){access.requireHrOrAdmin(r);return leaves.findAllByOrderByAppliedOnDesc();}
    @PostMapping("/leave") public LeaveRequest applyLeave(@Valid @RequestBody LeaveRequestDto x,HttpServletRequest r){Employee e=access.currentEmployee(r);if(x.endDate().isBefore(x.startDate()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"End date must be after start date");LeaveRequest l=new LeaveRequest();l.setEmployeeId(e.getId());l.setStartDate(x.startDate());l.setEndDate(x.endDate());l.setLeaveType(x.leaveType());l.setReason(x.reason());LeaveRequest saved=leaves.save(l);notifications.notifyUser(e.getTeamConnectUserId(),"Leave request submitted","Your leave request was submitted for review.");return saved;}
    @PatchMapping("/leave/{id}/status") public LeaveRequest leaveStatus(@PathVariable Long id,@RequestParam String status,HttpServletRequest r){access.requireHrOrAdmin(r);LeaveRequest l=leaves.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Leave request not found"));l.setStatus(status.toUpperCase(Locale.ROOT));l.setReviewedBy(access.userId(r));LeaveRequest saved=leaves.save(l);employees.findById(l.getEmployeeId()).ifPresent(e->{notifications.notifyUser(e.getTeamConnectUserId(),"Leave request updated","Your leave request is now " + l.getStatus() + ".");notifications.email(e.getEmail(),"Leave request updated","Your leave request is now " + l.getStatus() + ".");});return saved;}

    @GetMapping("/payroll/me") public List<SalaryRecord> myPayroll(HttpServletRequest r){return payroll.findByEmployeeIdOrderByPaymentDateDesc(access.currentEmployee(r).getId());}
    @GetMapping("/payroll/{employeeId}") public List<SalaryRecord> employeePayroll(@PathVariable Long employeeId,HttpServletRequest r){access.requireHrOrAdmin(r);return payroll.findByEmployeeIdOrderByPaymentDateDesc(employeeId);}
    @PostMapping("/payroll") public SalaryRecord createPayroll(@Valid @RequestBody PayrollRequest x,HttpServletRequest r){access.requireHrOrAdmin(r);SalaryRecord s=new SalaryRecord();s.setEmployeeId(x.employeeId());s.setAmount(x.amount());s.setPaymentDate(x.paymentDate());s.setPeriodLabel(x.periodLabel());s.setStatus(x.status());s.setNotes(x.notes());SalaryRecord saved=payroll.save(s);employees.findById(x.employeeId()).ifPresent(e->{notifications.notifyUser(e.getTeamConnectUserId(),"Payroll processed","A payroll record was processed for " + x.periodLabel());notifications.email(e.getEmail(),"Payroll processed","A payroll record was processed for " + x.periodLabel());});return saved;}

    @GetMapping("/performance/me") public List<PerformanceReview> myReviews(HttpServletRequest r){return reviews.findByEmployeeIdOrderByReviewDateDesc(access.currentEmployee(r).getId());}
    @PostMapping("/performance") public PerformanceReview createReview(@Valid @RequestBody PerformanceRequest x,HttpServletRequest r){access.requireHrOrAdmin(r);PerformanceReview p=new PerformanceReview();p.setEmployeeId(x.employeeId());p.setReviewerEmployeeId(x.reviewerEmployeeId());p.setRating(x.rating());p.setReviewContent(x.reviewContent());p.setReviewDate(x.reviewDate());p.setStatus(x.status());PerformanceReview saved=reviews.save(p);employees.findById(x.employeeId()).ifPresent(e->notifications.notifyUser(e.getTeamConnectUserId(),"Performance review created","A new performance review is available in TeamConnect."));return saved;}

    @GetMapping("/documents/me") public List<EmployeeDocument> myDocuments(HttpServletRequest r){return documents.findByEmployeeIdOrderByUploadedAtDesc(access.currentEmployee(r).getId());}
    @PostMapping(value="/documents",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public EmployeeDocument upload(@RequestParam("employeeId") Long employeeId,@RequestParam("file") MultipartFile file,HttpServletRequest r)throws IOException{access.requireEmployee(r,employeeId);if(file==null||file.isEmpty()||file.getSize()>20_000_000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"File is empty or exceeds 20 MB");Path root=Path.of(fileDirectory).toAbsolutePath().normalize();Files.createDirectories(root);String key=UUID.randomUUID().toString();Files.copy(file.getInputStream(),root.resolve(key),StandardCopyOption.REPLACE_EXISTING);EmployeeDocument d=new EmployeeDocument();d.setEmployeeId(employeeId);d.setOriginalName(Optional.ofNullable(file.getOriginalFilename()).orElse("document").replaceAll("[\\\"\\r\\n]","_"));d.setStorageKey(key);d.setContentType(Optional.ofNullable(file.getContentType()).orElse("application/octet-stream"));d.setFileSize(file.getSize());d.setUploadedBy(access.userId(r));EmployeeDocument saved=documents.save(d);employees.findById(employeeId).ifPresent(e->notifications.notifyUser(e.getTeamConnectUserId(),"Document uploaded","A document was uploaded to your employee profile."));return saved;}
    @GetMapping("/documents/{id}/download") public ResponseEntity<InputStreamResource> download(@PathVariable Long id,HttpServletRequest r)throws IOException{EmployeeDocument d=documents.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Document not found"));access.requireEmployee(r,d.getEmployeeId());Path root=Path.of(fileDirectory).toAbsolutePath().normalize();Path p=root.resolve(d.getStorageKey()).normalize();if(!p.startsWith(root)||!Files.exists(p))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Document file not found");return ResponseEntity.ok().contentType(MediaType.parseMediaType(d.getContentType())).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+d.getOriginalName().replaceAll("[\\\"\\r\\n]","_")+"\"").body(new InputStreamResource(Files.newInputStream(p)));}

    @GetMapping("/announcements") public List<Announcement> announcementList(HttpServletRequest r){access.userId(r);return announcements.findTop30ByOrderByPublishedAtDesc();}
    @PostMapping("/announcements") public Announcement announce(@Valid @RequestBody AnnouncementRequest x,HttpServletRequest r){access.requireAdmin(r);Announcement a=new Announcement();a.setTitle(x.title());a.setBody(x.body());a.setAudience(x.audience().toUpperCase(Locale.ROOT));a.setCreatedBy(access.userId(r));Announcement saved=announcements.save(a);employees.findAll().forEach(e->notifications.notifyUser(e.getTeamConnectUserId(),x.title(),x.body()));return saved;}
    @GetMapping("/reports/summary") public Map<String,Object> report(HttpServletRequest r){access.requireHrOrAdmin(r);return Map.of("employees",employees.count(),"activeEmployees",employees.findAll().stream().filter(e->"ACTIVE".equalsIgnoreCase(e.getStatus())).count(),"departments",departments.count(),"projects",projects.count(),"leaveRequests",leaves.count(),"attendanceRecords",attendance.count(),"documents",documents.count(),"performanceReviews",reviews.count());}
    @GetMapping("/settings") public List<SystemSetting> settings(HttpServletRequest r){access.requireAdmin(r);return settings.findAll();}
    @PutMapping("/settings/{key}") public SystemSetting setting(@PathVariable String key,@RequestParam String value,HttpServletRequest r){access.requireAdmin(r);SystemSetting s=settings.findById(key).orElse(new SystemSetting(key,value));s.setValue(value);return settings.save(s);}

    private Employee employeeFrom(EmployeeRequest x){Employee e=new Employee();copy(e,x);return e;} private void copy(Employee e,EmployeeRequest x){e.setEmsEmployeeId(x.emsEmployeeId());e.setTeamConnectUserId(x.teamConnectUserId());e.setName(x.name());e.setEmail(x.email());e.setPhone(x.phone());e.setGender(x.gender());e.setJobTitle(x.jobTitle());e.setHireDate(x.hireDate());e.setSalary(x.salary());e.setAddress(x.address());e.setRole(x.role().toUpperCase(Locale.ROOT));e.setStatus(x.status().toUpperCase(Locale.ROOT));if(x.departmentId()!=null)e.setDepartment(departments.findById(x.departmentId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Department not found")));}
    private Project projectFrom(ProjectRequest x){Project p=new Project();p.setProjectName(x.projectName());p.setDescription(x.description());p.setStartDate(x.startDate());p.setEndDate(x.endDate());p.setStatus(x.status());return p;}
}
